public class BookingReceiptSettlement { static final class BookingReceipt{final String id;final int[] seats;BookingReceipt(String id,int[] s){this.id=id;seats=s.clone();}int[] getSeats(){return seats.clone();}}static String settle(BookingReceipt[] r){int ok=0,nil=0;for(BookingReceipt x:r)if(x==null)nil++;else ok++;return ok+" processed | "+nil+" null skipped";}public static void main(String[]a){System.out.println(settle(new BookingReceipt[]{new BookingReceipt("B1",new int[]{1}),null}));} }
